  CONSTRAINT "booking_ends_at_format" CHECK (((('date-time' = 'date') AND ("ends_at" ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$')) OR (('date-time' = 'date-time') AND ("ends_at" ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$')))),
