  CONSTRAINT "booking_large_party_pays_deposit" CHECK ((("party_size" < 7) OR (("deposit" IS NOT NULL) AND ("deposit" > 0)))),
  CONSTRAINT "booking_ends_after_start" CHECK ((("ends_at")::TIMESTAMPTZ > (("starts_at")::TIMESTAMPTZ + INTERVAL '1800000 milliseconds')))
